def fix_scenario(start_year_row, scenario_num):
    """Fix the bell shape formula for a scenario"""
    # Find the investment amount cell
    for row in range(start_year_row - 10, start_year_row):
        if ws_na[f'A{row}'].value == 'Investment Amount (USD millions)':
            inv_amt_cell = f'B{row}'
            break

    # Fix each year (rows should be 8 years starting from start_year_row)
    for offset in range(8):
        year = ws_na[f'A{start_year_row + offset}'].value
        if year and 2026 <= year <= 2033:
            year_idx = year - 2025  # 1-8

            # Correct bell shape formula
            if year_idx <= 4:
                ws_na[f'B{start_year_row + offset}'] = f"={year_idx}/4*${inv_amt_cell}"
            else:
                # For years 5-8: (9 - year_idx) / 4
                ws_na[f'B{start_year_row + offset}'] = f"={(9-year_idx)}/4*${inv_amt_cell}"

